<?php use Hls\Http\View as V; ?><section class="panel"><form method="post" class="form-grid"><?= $this->csrf() ?><label>Kode tarif<input name="rate_code" required></label><label>Nama tarif<input name="description" required></label><label>Cabang<select name="branch_id"><option value="">Semua cabang</option><?php foreach($branches as $b): ?><option value="<?= (int)$b['id'] ?>"><?= V::escape($b['name']) ?></option><?php endforeach ?></select></label><label>Tarif per jam<input type="number" name="rate_per_hour" min="0" step="0.01" required></label><label>Berlaku mulai<input type="date" name="effective_from" required></label><label>Berlaku sampai<input type="date" name="effective_until"></label><button class="button primary">Simpan Tarif</button></form></section><section class="panel"><div class="table-scroll"><table><thead><tr><th>Kode</th><th>Tarif</th><th>Cabang</th><th>Periode</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= V::escape($r['rate_code']) ?></td><td><?= \Hls\Http\View::money($r['rate_per_hour']) ?>/jam</td><td><?= V::escape($r['branch_name']?:'Semua cabang') ?></td><td><?= V::escape($r['effective_from'].' - '.($r['effective_until']?:'sekarang')) ?></td><td><?= $r['active']?'Aktif':'Nonaktif' ?></td></tr><?php endforeach ?></tbody></table><?php if(!$rows): ?><p class="empty-state">Belum ada tarif mekanik.</p><?php endif ?></div></section>
